    46	    public Pedido registrar(DadosCompra dados) {
    48	        Checkout checkout = calculadora.calcular(dados);
    49	        Instant agora = relogio.instant().truncatedTo(ChronoUnit.SECONDS);
    50	        return transacao.execute(status -> {
    51	            clientes.garantir(dados.cpf(), dados.email());
    52	            long id = pedidos.inserir(checkout, agora);
    53	            return pedidos.buscar(id).orElseThrow();
    54	        });
    55	    }
