   122	    private Pedido cancelarTravado(Pedido pedido) {
   123	        boolean estornar = pedido.situacao().pagamentoConfirmado();
   124	        pedidos.mudarSituacao(pedido.id(), SituacaoPedido.CANCELADO);
   125	        if (estornar) {
