    59	    public void devolver(Map<String, Integer> quantidades) {
    60	        new TreeMap<>(quantidades).forEach((sku, quantidade) ->
    61	                jdbc.sql("UPDATE produto SET estoque = estoque + :quantidade WHERE sku = :sku")
    62	                        .param("quantidade", quantidade)
    63	                        .param("sku", sku)
    64	                        .update());
