        {"arquivo": "src/main/java/br/com/loja/pedidos/checkout/entrega/Indisponivel.java", "linha": 15, "o_que_mostra": "a regra de entrega escreve o literal HTTP 503 para TRANSPORTADORA_INDISPONIVEL"},
        {"arquivo": "src/main/java/br/com/loja/pedidos/checkout/entrega/Indisponivel.java", "linha": 11, "o_que_mostra": "MODALIDADE_INDISPONIVEL criado com naoProcessavel (422) dentro do pacote de entrega"},
        {"arquivo": "src/main/java/br/com/loja/pedidos/checkout/CalculadoraCheckout.java", "linha": 124, "o_que_mostra": "o cálculo do checkout cria todas as recusas com o status 422"},
        {"arquivo": "src/main/java/br/com/loja/pedidos/checkout/cupom/Cupons.java", "linha": 24, "o_que_mostra": "a regra de cupom escolhe 422 para CUPOM_INVALIDO"},
